import math

def clamp(x, a, b):
    return max(a, min(b, x))

def interp(points, u):
    pts = sorted(points, key=lambda p: p[0])
    if not pts:
        return None
    if u <= pts[0][0]:
        return pts[0][1]
    for (u0,v0),(u1,v1) in zip(pts, pts[1:]):
        if u0 <= u <= u1:
            f = (u-u0)/(u1-u0) if u1 != u0 else 0.0
            return v0 + f*(v1-v0)
    return pts[-1][1]

def control(obs):
    mp = obs.get('local_map', {})
    left = mp.get('left_rail', [])
    right = mp.get('right_rail', [])
    targets = []
    for u in (4.0, 6.0, 8.0):
        l = interp(left, u)
        r = interp(right, u)
        if l is not None and r is not None:
            targets.append((u, (l+r)/2.0))
    lateral = sum(v for _,v in targets)/len(targets) if targets else 0.0
    bearing = float(obs.get('route', {}).get('bearing_deg', 0.0))
    hitch = float(obs.get('hitch_deg', 0.0))
    steer = clamp(1.05*hitch - 8.0*lateral - 0.45*bearing, -28.0, 28.0)
    return (steer, -0.75, 180.0)

