import math
def clamp(x, lo, hi): return max(lo, min(hi, x))
def control(obs):
    hitch = float(obs.get('hitch_deg', 0.0))
    # Find the course centreline from the local rail map at a short lookahead.
    lm = obs.get('local_map') or {}
    left, right = lm.get('left_rail') or [], lm.get('right_rail') or []
    target_v = 0.0
    found = False
    # Average corresponding rail points near 3 m ahead of the trailer rear.
    if left and right:
        pairs = []
        for a in left:
            for b in right:
                if abs(float(a[0])-float(b[0])) < 0.04:
                    u = (float(a[0])+float(b[0]))/2
                    if 2.3 <= u <= 4.2:
                        pairs.append((u, (float(a[1])+float(b[1]))/2))
                    break
        if pairs:
            target_v = sum(v for u,v in pairs)/len(pairs)
            found = True
    bearing = math.atan2(target_v, 3.2) if found else math.radians(float((obs.get('route') or {}).get('bearing_deg', 0.0)))
    # On reverse, steering left sends the trailer rear right; add hitch damping.
    steer = 0.78*hitch - 24.0*math.degrees(bearing)
    steer = clamp(steer, -24.0, 24.0)
    # Cautious pace allows enough wheel movement per metre through the bend.
    speed = -0.48
    if abs(hitch) > 25: speed = -0.32
    if obs.get('status') == 'JACKKNIFED': speed = 0.0
    return (steer, speed, 180)

