import math

def clamp(x, lo, hi):
    return max(lo, min(hi, x))

def control(obs):
    mp = obs.get('local_map', {})
    left = mp.get('left_rail', [])
    right = mp.get('right_rail', [])
    pairs = []
    for p in left:
        u, vl = p[0], p[1]
        if u < 0:
            continue
        q = min(right, key=lambda z: abs(z[0]-u)) if right else None
        if q is not None and abs(q[0]-u) < 2.0:
            pairs.append((u, (vl+q[1])*0.5))
    pairs.sort()
    def center_at(target):
        if not pairs:
            return 0.0
        return min(pairs, key=lambda a: abs(a[0]-target))[1]
    c5, c15 = center_at(5.0), center_at(15.0)
    slope = clamp((c15-c5)/10.0, -0.45, 0.45)
    hitch = float(obs.get('hitch_deg', 0.0))
    steer = clamp(-math.degrees(math.atan(slope))*0.75 + hitch*0.9, -18.0, 18.0)
    speed = -0.75
    if abs(hitch) > 15 or abs(slope) > 0.25:
        speed = -0.45
    return (steer, speed, 180)

